UPDATE tb_warehouse
name = #{warehouseDto.name}, build_time = #{warehouseDto.buildTime}, code = #{warehouseDto.code}, use_volume = #{warehouseDto.useVolume}, use_volume_unit = #{warehouseDto.useVolumeUnit}, use_area = #{warehouseDto.useArea}, use_area_unit = #{warehouseDto.useAreaUnit}, is_automation = #{warehouseDto.isAutomation}, is_statistics = #{warehouseDto.isStatistics}, is_using = #{warehouseDto.isUsing}, remark = #{warehouseDto.remark}, last_updated_user = #{warehouseDto.username}, last_updated_time = sysdate()
WHERE id = #{warehouseDto.id}

UPDATE tb_building
building_no = #{buildingDto.buildingNo}, use_volume = #{buildingDto.useVolume}, use_volume_unit= #{buildingDto.useVolumeUnit}, use_area = #{buildingDto.useArea}, use_area_unit = #{buildingDto.useAreaUnit}, building_orientation = #{buildingDto.buildingOrientation}, remark = #{buildingDto.remark}, last_updated_user = #{buildingDto.updateUser}, warehouse_id = #{buildingDto.warehouseId}, pid_route = #{buildingDto.pidRoute}, building_name = #{buildingDto.buildingName}, site_name = #{buildingDto.siteName}, last_updated_time = sysdate()
WHERE id = #{buildingDto.id}

UPDATE tb_floor
floor_no = #{floorDto.floorNo}, is_partition= #{floorDto.isPartition}, remark = #{floorDto.remark}, last_updated_user = #{floorDto.updateUser}, building_id = #{floorDto.buildingId}, pid_route = #{floorDto.pidRoute}, floor_name = #{floorDto.floorName}, site_name = #{floorDto.siteName}, last_updated_time = sysdate()
WHERE id = #{floorDto.id}
